size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate, CompressionType compression,
                       ExceptionInfo *exception) {
  size_t number_pixels = 0;
  ssize_t y;
  unsigned char *pixels = NULL;
  MagickOffsetType length = 0;
  size_t count = 0;
  MagickBooleanType status = MagickTrue;

  if (next_image == (Image *) NULL)
    return 0;

  if ((compression != RLECompression) && (compression != ZipCompression))
    compression = NoCompression;

  pixels = (unsigned char *) AcquireMemory(image->columns * 4);
  if (pixels == (unsigned char *) NULL)
    compression = NoCompression;

  for (y = 0; y < (ssize_t) image->rows; y++) {
    ExportPixelPacket(image, next_image, &pixels[count], quantum_type);
    count += image->columns;
  }

  number_pixels = image->columns * image->rows;

  if (compression != NoCompression) {
    register ssize_t i;
    register unsigned char *p = compact_pixels;

    for (i = 0; i < (ssize_t) number_pixels; i++) {
      *p++ = compact_pixels[i];
    }
    compact_pixels = pixels;
    length = number_pixels;
  }

  if ((compression == RLECompression) || (compression == ZipCompression)) {
    size_offset += WriteBlobPSDChannel(image, compression, compact_pixels, length,
                                       exception);
  } else {
    size_offset += WriteBlobPSDChannel(image, NoCompression, compact_pixels, length,
                                       exception);
  }

  if (pixels != (unsigned char *) NULL)
    pixels = (unsigned char *) RelinquishMemory(pixels);

  return (size_offset);
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate, CompressionType compression,
                       ExceptionInfo *exception) {
  size_t number_pixels = 0;
  size_t written = 0;
  unsigned char *pixels = NULL;
  MagickOffsetType y;
  size_t width = image->columns;
  size_t height = image->rows;

  if ((compression == ZipCompression) || (compression == ZipSCompression))
  {
    /* Compressed data handling */
    pixels = (unsigned char *) AcquireMemory(height * width * sizeof(unsigned char));
    if (pixels == (unsigned char *) NULL)
      ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", "WritePSDChannel");
  }

  for (y = 0; y < (MagickOffsetType) height; y++)
  {
    /* Export row of pixels */
    ExportPixelPacket(image, (PixelPacket *) (compact_pixels + y * width * sizeof(unsigned char)), width, 1, (MagickBooleanType) MagickFalse, exception);

    if ((compression == ZipCompression) || (compression == ZipSCompression))
    {
      /* Apply ZIP compression */
      (void) compress((Bytef *) pixels + y * width, &number_pixels, (const Bytef *) compact_pixels + y * width, width);
    }
    else if (compression == RLECompression)
    {
      /* Apply RLE compression */
      (void) RLECompress(psd_info, compact_pixels + y * width, width, (unsigned char **) &pixels, &number_pixels, exception);
    }

    written += WriteBlob(image, number_pixels, pixels + y * width);
  }

  if ((compression == ZipCompression) || (compression == ZipSCompression))
    RelinquishMemory(pixels);

  return written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate, CompressionType compression,
                       ExceptionInfo *exception) {
  size_t total_bytes_written = 0;
  MagickOffsetType offset = size_offset;
  size_t rows = image->rows;
  size_t columns = image->columns;
  size_t length;
  unsigned char *pixels = NULL;
  unsigned char *q;

  if (compression == RLECompression || compression == ZipCompression)
  {
    pixels = (unsigned char *) AcquireMemory(rows * columns * sizeof(*pixels));
    if (pixels == (unsigned char *) NULL)
      ThrowBinaryException(ResourceLimitError, "Memory allocation failed", image_info->filename);
  }

  for (size_t y = 0; y < rows; y++)
  {
    q = compact_pixels + (y * columns);
    ExportPixelRow(image, next_image, y, q, quantum_type, exception);
  }

  if (compression == RLECompression)
  {
    length = RLECompress(compact_pixels, columns, rows, pixels);
    total_bytes_written += length;
    offset += WriteBlobMemory(image, length, pixels);
  }
  else if (compression == ZipCompression)
  {
    length = ZipCompress(compact_pixels, columns, rows, pixels);
    total_bytes_written += length;
    offset += WriteBlobMemory(image, length, pixels);
  }
  else
  {
    length = rows * columns;
    total_bytes_written += length;
    offset += WriteBlobMemory(image, length, compact_pixels);
  }

  if (pixels != (unsigned char *) NULL)
    pixels = RelinquishMemory(pixels);

  return total_bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, CompressionType compression, ExceptionInfo *exception) {
    size_t bytes_written = 0;
    ssize_t y;
    MagickBooleanType status = MagickTrue;
    MagickSizeType length;
    unsigned char *pixels = NULL;
    size_t rows;

    rows = image->rows;
    pixels = (unsigned char *) AcquireMemory((size_t) (image->columns * rows * 4));
    if (pixels == (unsigned char *) NULL)
        ThrowPSDException(ResourceLimitError, "MemoryAllocationFailed", image_info->filename);

    for (y = 0; y < (ssize_t) rows; y++) {
        if (next_image == (Image *) NULL) {
            (void) ExportPixelRow(image, (const IndexPacket *) NULL, pixels, (ssize_t) y, quantum_type);
        }
        else {
            (void) ExportPixelRow(next_image, (const IndexPacket *) NULL, pixels, (ssize_t) y, quantum_type);
        }

        switch (compression) {
            case RLECompression:
                length = CompressRLE(pixels, image->columns, 4, compact_pixels + bytes_written);
                if (length < 0) {
                    status = MagickFalse;
                    break;
                }
                break;
            case ZIPCompression:
                length = CompressZIP(pixels, image->columns, 4, compact_pixels + bytes_written);
                if (length < 0) {
                    status = MagickFalse;
                    break;
                }
                break;
            default:
                length = (MagickSizeType) image->columns * 4;
                (void) memcpy(compact_pixels + bytes_written, pixels, (size_t) length);
                break;
        }

        bytes_written += (size_t) length;
    }

    if (pixels != (unsigned char *) NULL)
        pixels = RelinquishMemory(pixels);

    if (!status)
        bytes_written = 0;

    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate, CompressionType compression,
                       ExceptionInfo *exception) {
  size_t total_bytes_written = 0;

  if (next_image == (Image *) NULL)
    return total_bytes_written;

  if (compression == ZipCompression || compression == RLECompression) {
    size_t rows_written = 0;
    unsigned char *compressed_pixels = NULL;
    size_t compressed_pixels_length = 0;

    MagickBooleanType status = MagickTrue;

    for (size_t y = 0; y < image->rows && status != MagickFalse; y++) {
      MagickPixelPacket *pixels = ExportPixelRow(next_image, y, quantum_type);

      if (pixels == (MagickPixelPacket *) NULL) {
        continue;
      }

      if (compression == RLECompression) {
        // Apply RLE compression
        compressed_pixels = CompressRLE(pixels, &compressed_pixels_length);
      } else if (compression == ZipCompression) {
        // Apply ZIP compression
        compressed_pixels = CompressZIP(pixels, &compressed_pixels_length);
      }

      if (compressed_pixels != NULL) {
        if (WriteBlobMemory(image, compressed_pixels_length, compressed_pixels) ==
            MagickFalse) {
          status = MagickFalse;
          break;
        }

        total_bytes_written += compressed_pixels_length;
        rows_written++;
      }

      // Free allocated resources
      if (compressed_pixels != NULL)
        MagickFreeMemory(compressed_pixels);
    }

    if (status == MagickFalse) {
      // Error handling
      CatchException(exception);
    }
  }

  return total_bytes_written;
}
